package com.enterprisehub.api;
import com.enterprisehub.repo.*; import com.enterprisehub.domain.Department; import com.enterprisehub.service.RequestService; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api") public class AdminController { private final DepartmentRepository departments; private final EmployeeRepository employees; private final RequestService requests; public AdminController(DepartmentRepository d,EmployeeRepository e,RequestService r){departments=d;employees=e;requests=r;} @GetMapping("/departments") public Object departments(){return departments.findAll();} @org.springframework.security.access.prepost.PreAuthorize("hasRole('ADMIN')") @GetMapping("/employees") public Object employees(){return employees.findAll().stream().map(u->java.util.Map.of("id",u.id,"name",u.name,"email",u.email,"role",u.role,"department",u.department.name)).toList();} @org.springframework.security.access.prepost.PreAuthorize("hasAnyRole('ADMIN','MANAGER')") @GetMapping({"/analytics/overview","/analytics/dashboard"}) public Object analytics(){return requests.analytics();} @org.springframework.security.access.prepost.PreAuthorize("hasRole('ADMIN')") @PostMapping("/departments") public Object addDepartment(@RequestBody Department d){return departments.save(d);} }
